import heapq

class Solution:
    def smallestChair(self, times: list[list[int]], targetFriend: int) -> int:
        events = []
        for i, (arr, leave) in enumerate(times):
            events.append((arr, leave, i))
        events.sort()

        available_chairs = list(range(len(times)))
        heapq.heapify(available_chairs)
        leaving_heap = []

        for arr, leave, i in events:
            while leaving_heap and leaving_heap[0][0] <= arr:
                _, chair = heapq.heappop(leaving_heap)
                heapq.heappush(available_chairs, chair)

            assigned_chair = heapq.heappop(available_chairs)
            if i == targetFriend:
                return assigned_chair
            heapq.heappush(leaving_heap, (leave, assigned_chair))
        return -1

class Solution {
public:
    int smallestChair(vector<vector<int>>& times, int targetFriend) {
        int n = times.size();
        vector<tuple<int, int, int>> events;
        for (int i = 0; i < n; i++) events.push_back({times[i][0], times[i][1], i});
        sort(events.begin(), events.end());

        priority_queue<int, vector<int>, greater<int>> available;
        for (int i = 0; i < n; i++) available.push(i);

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> leaving;

        for (auto& [arr, leave, idx] : events) {
            while (!leaving.empty() && leaving.top().first <= arr) {
                available.push(leaving.top().second);
                leaving.pop();
            }
            int chair = available.top();
            available.pop();
            if (idx == targetFriend) return chair;
            leaving.push({leave, chair});
        }
        return -1;
    }
};

class Solution {
    public int smallestChair(int[][] times, int targetFriend) {
        int n = times.length;
        int[][] events = new int[n][3];
        for (int i = 0; i < n; i++) {
            events[i][0] = times[i][0];
            events[i][1] = times[i][1];
            events[i][2] = i;
        }
        java.util.Arrays.sort(events, (a, b) -> Integer.compare(a[0], b[0]));

        java.util.PriorityQueue<Integer> available = new java.util.PriorityQueue<>();
        for (int i = 0; i < n; i++) available.offer(i);

        java.util.PriorityQueue<int[]> leaving = new java.util.PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));

        for (int[] e : events) {
            int arr = e[0], leave = e[1], idx = e[2];
            while (!leaving.isEmpty() && leaving.peek()[0] <= arr) {
                available.offer(leaving.poll()[1]);
            }
            int chair = available.poll();
            if (idx == targetFriend) return chair;
            leaving.offer(new int[]{leave, chair});
        }
        return -1;
    }
}

var smallestChair = function(times, targetFriend) {
  const n = times.length;
  const events = times.map((t, i) => [t[0], t[1], i]);
  events.sort((a, b) => a[0] - b[0]);

  const available = Array.from({ length: n }, (_, i) => i);
  const leaving = []; // [leaveTime, chair]

  for (const [arr, leave, idx] of events) {
    leaving.sort((a, b) => a[0] - b[0]);
    while (leaving.length > 0 && leaving[0][0] <= arr) {
      const [_, chair] = leaving.shift();
      available.push(chair);
      available.sort((a, b) => a - b);
    }
    const chair = available.shift();
    if (idx === targetFriend) return chair;
    leaving.push([leave, chair]);
  }
  return -1;
};
